<section class="card"><h2>01 · ترشيح الطلبة للمواد</h2><form method="post"><?=csrf()?><input type="hidden" name="action" value="enroll"><input type="hidden" name="period_id" value="<?=(int)$p['id']?>"><div class="grid"><?php $subjects=[];foreach(rows('SELECT b.*,d.name AS department,t.name AS stage FROM subjects b JOIN departments d ON d.id=b.department_id JOIN stages t ON t.id=b.stage_id WHERE b.institution_id=? ORDER BY b.name',[inst()]) as $b)$subjects[$b['id']]=$b['name'].' — '.$b['department'].' / '.$b['stage'];selectf('المادة (تحدد القسم والمرحلة)','subject_id',$subjects);selectf('الدراسة — اختياري','shift',['صباحي'=>'صباحي','مسائي'=>'مسائي'],'',false);field('الشعبة — اختياري','section_name','','text','',false);$studentOptions=[];foreach(rows('SELECT * FROM students WHERE institution_id=? AND year_id=? AND active=1 ORDER BY name',[inst(),$p['year_id']]) as $s)$studentOptions[$s['id']]=$s['code'].' — '.$s['name'];selectf('طالب منفرد / محمّل مادة — أو اتركه لترشيح المجموعة','student_id',$studentOptions,'',false);field('مرجع تحميل المادة — للطالب المنفرد فقط','carry_note','','text','',false);?></div><p class="muted">تُفحص أهلية الطالب للمادة وتعارضاته الزمنية. تحميل مادة من مرحلة أخرى في القسم نفسه يتطلب اختيار طالب منفرد والتأكيد ومرجع التحميل.</p><label class="check"><input type="checkbox" name="allow_carry" value="1">طالب منفرد محمّل بمادة من مرحلة أخرى في القسم نفسه، مع مرجع موثق.</label><button>ترشيح الطلبة المؤهلين</button></form></section>
<section class="card"><h2>02 · توليد التوزيع ومراجعته</h2><div class="actions"><?php foreach(['generate'=>'توزيع الطلبة آليًا','monitors'=>'توزيع المراقبين','clear'=>'إفراغ المسودة'] as $action=>$label):?><form method="post" data-confirm="<?=h($action==='generate'?'إعادة التوزيع ستحفظ نسخة وتلغي توزيع المراقبين الحالي.':($action==='clear'?'ستُحفظ نسخة ثم تُفرغ المقاعد والتكليفات. هل تتابع؟':'توليد تكليفات جديدة بحسب التفرغ والعبء؟'))?>"><?=csrf()?><input type="hidden" name="action" value="<?=$action?>"><input type="hidden" name="period_id" value="<?=(int)$p['id']?>"><button class="<?=$action==='clear'?'secondary danger':($action==='monitors'?'secondary':'')?>"><?=$label?></button></form><?php endforeach;?></div><p class="muted">التوزيع قابل لإعادة الإنتاج بالمدخلات نفسها، ويجرّب القاعات العادية قبل الاحتياطية. عند انتهاء حد البحث الإلزامي لا يُحفظ حل ناقص، ولا تعني الرسالة إثبات استحالة الحل.</p></section>
