<section class="card"><h2>المرشحون والمواد</h2><div class="table-wrap"><table><tr><th>الرمز</th><th>الاسم</th><th>المادة</th><th>القسم / المرحلة</th><th>إجراء</th></tr><?php foreach($candidates as $s):?><tr><td><?=h($s['code'])?></td><td><?=h($s['name'])?></td><td><?=h($s['subject'])?><small><?=h($s['carry_note']??'')?></small></td><td><?=h($s['department'].' / '.$s['stage'])?></td><td><?php if(can('write')&&$draft&&!$assigned):?><form method="post" class="inline"><?=csrf()?><input type="hidden" name="action" value="remove-candidate"><input type="hidden" name="period_id" value="<?=(int)$p['id']?>"><input type="hidden" name="student_id" value="<?=(int)$s['id']?>"><button class="ghost danger">إزالة الترشيح</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></section>
